import { spawn } from "node:child_process";
import { StringDecoder } from "node:string_decoder";
export const DEFAULT_MAX_LOGCAT_SUBSCRIBERS = 8;
export const DEFAULT_LOGCAT_BATCH_INTERVAL_MS = 75;
export const DEFAULT_LOGCAT_QUEUE_LINES = 256;
export const DEFAULT_LOGCAT_QUEUE_BYTES = 256 * 1024;
export const DEFAULT_LOGCAT_MAX_LINE_BYTES = 16 * 1024;
export const DEFAULT_LOGCAT_PID_REFRESH_MS = 5_000;
export const DEFAULT_LOGCAT_TERMINATION_GRACE_MS = 1_000;
const LOGCAT_PID_LOOKUP_TIMEOUT_MS = 2_000;
const LOGCAT_PID_LOOKUP_MAX_OUTPUT_BYTES = 64 * 1024;
const SYSTEM_CLOCK = {
    setTimeout: (callback, delayMs)=>setTimeout(callback, delayMs),
    clearTimeout: (timer)=>clearTimeout(timer),
    setInterval: (callback, delayMs)=>setInterval(callback, delayMs),
    clearInterval: (timer)=>clearInterval(timer)
};
function positiveInteger(value, name) {
    if (!Number.isSafeInteger(value) || value < 1) {
        throw new TypeError(`${name} must be a positive safe integer`);
    }
    return value;
}
async function resolvePackagePids(serial, packageName, signal) {
    if (!/^[A-Za-z0-9_.:-]+$/.test(packageName) || signal.aborted) {
        return new Set();
    }
    return new Promise((resolve)=>{
        let child;
        let timer = null;
        let outputBytes = 0;
        let failed = false;
        let killRequested = false;
        const stdoutChunks = [];
        const kill = ()=>{
            failed = true;
            if (killRequested) return;
            killRequested = true;
            try {
                child.kill("SIGKILL");
            } catch  {}
        };
        const onAbort = ()=>kill();
        const collect = (target, value)=>{
            const chunk = Buffer.isBuffer(value) ? value : Buffer.from(value);
            if (chunk.byteLength > LOGCAT_PID_LOOKUP_MAX_OUTPUT_BYTES - outputBytes) {
                kill();
                return;
            }
            outputBytes += chunk.byteLength;
            if (target === "stdout") stdoutChunks.push(chunk);
        };
        const finish = (status)=>{
            if (timer) clearTimeout(timer);
            signal.removeEventListener("abort", onAbort);
            if (failed || status !== 0) {
                resolve(new Set());
                return;
            }
            resolve(new Set(Buffer.concat(stdoutChunks).toString("utf8").trim().split(/\s+/).filter(Boolean)));
        };
        try {
            child = spawn("adb", [
                "-s",
                serial,
                "shell",
                "pidof",
                packageName
            ], {
                stdio: [
                    "ignore",
                    "pipe",
                    "pipe"
                ]
            });
        } catch  {
            resolve(new Set());
            return;
        }
        signal.addEventListener("abort", onAbort, {
            once: true
        });
        timer = setTimeout(kill, LOGCAT_PID_LOOKUP_TIMEOUT_MS);
        child.stdout.on("data", (chunk)=>{
            collect("stdout", chunk);
        });
        child.stderr.on("data", (chunk)=>{
            collect("stderr", chunk);
        });
        child.once("error", ()=>{
            failed = true;
        });
        child.stdout.once("error", kill);
        child.stderr.once("error", kill);
        child.once("close", (status)=>finish(status));
        if (signal.aborted) onAbort();
    });
}
function spawnLogcat(serial) {
    // Start at the live edge so reconnects do not replay the device ring buffer.
    return spawn("adb", [
        "-s",
        serial,
        "logcat",
        "-T",
        "1",
        "-v",
        "threadtime"
    ], {
        stdio: [
            "ignore",
            "pipe",
            "pipe"
        ]
    });
}
function encodeEvent(event, value) {
    return new TextEncoder().encode(`event: ${event}\ndata: ${JSON.stringify(value)}\n\n`);
}
class BoundedLineQueue {
    maxLines;
    maxBytes;
    #entries = [];
    #head = 0;
    #bytes = 0;
    #droppedSinceFlush = 0;
    constructor(maxLines, maxBytes){
        this.maxLines = maxLines;
        this.maxBytes = maxBytes;
    }
    get lineCount() {
        return this.#entries.length - this.#head;
    }
    get byteCount() {
        return this.#bytes;
    }
    push(value) {
        const bytes = Buffer.byteLength(value.line, "utf8") + Buffer.byteLength(value.at, "utf8");
        let dropped = 0;
        if (bytes > this.maxBytes) {
            this.#droppedSinceFlush++;
            return 1;
        }
        while(this.lineCount >= this.maxLines || this.#bytes + bytes > this.maxBytes){
            const entry = this.#entries[this.#head++];
            if (!entry) break;
            this.#bytes -= entry.bytes;
            dropped++;
        }
        if (this.#head >= 64) {
            this.#entries = this.#entries.slice(this.#head);
            this.#head = 0;
        }
        this.#entries.push({
            value,
            bytes
        });
        this.#bytes += bytes;
        this.#droppedSinceFlush += dropped;
        return dropped;
    }
    drain() {
        const lines = this.#entries.slice(this.#head).map((entry)=>entry.value);
        const dropped = this.#droppedSinceFlush;
        this.#entries = [];
        this.#head = 0;
        this.#bytes = 0;
        this.#droppedSinceFlush = 0;
        return {
            lines,
            dropped
        };
    }
}
/**
 * One logcat child per immutable device session with bounded server-side
 * fan-out. Slow consumers drop their oldest queued lines and receive the drop
 * count in the next batch rather than growing ReadableStream queues forever.
 */ export class LogcatHub {
    serial;
    #maxSubscribers;
    #batchIntervalMs;
    #maxQueueLines;
    #maxQueueBytes;
    #maxSourceLineBytes;
    #pidRefreshMs;
    #terminationGraceMs;
    #spawn;
    #resolvePackagePids;
    #now;
    #clock;
    #subscribers = new Map();
    #decoder = new StringDecoder("utf8");
    #totals = {
        childStarts: 0,
        forcedKills: 0,
        batches: 0,
        deliveredLines: 0,
        droppedLines: 0,
        sourceDroppedLines: 0
    };
    #nextSubscriberId = 1;
    #child = null;
    #terminatingChild = null;
    #terminationTimer = null;
    #lineBuffer = "";
    #discardingLongLine = false;
    #activePidLookups = 0;
    #closed = false;
    #lastError = null;
    constructor(serial, options = {}){
        if (!serial) throw new TypeError("serial must not be empty");
        this.serial = serial;
        this.#maxSubscribers = positiveInteger(options.maxSubscribers ?? DEFAULT_MAX_LOGCAT_SUBSCRIBERS, "maxSubscribers");
        this.#batchIntervalMs = positiveInteger(options.batchIntervalMs ?? DEFAULT_LOGCAT_BATCH_INTERVAL_MS, "batchIntervalMs");
        this.#maxQueueLines = positiveInteger(options.maxQueueLines ?? DEFAULT_LOGCAT_QUEUE_LINES, "maxQueueLines");
        this.#maxQueueBytes = positiveInteger(options.maxQueueBytes ?? DEFAULT_LOGCAT_QUEUE_BYTES, "maxQueueBytes");
        this.#maxSourceLineBytes = positiveInteger(options.maxSourceLineBytes ?? DEFAULT_LOGCAT_MAX_LINE_BYTES, "maxSourceLineBytes");
        this.#pidRefreshMs = positiveInteger(options.pidRefreshMs ?? DEFAULT_LOGCAT_PID_REFRESH_MS, "pidRefreshMs");
        this.#terminationGraceMs = positiveInteger(options.terminationGraceMs ?? DEFAULT_LOGCAT_TERMINATION_GRACE_MS, "terminationGraceMs");
        this.#spawn = options.dependencies?.spawn ?? spawnLogcat;
        this.#resolvePackagePids = options.dependencies?.resolvePackagePids ?? resolvePackagePids;
        this.#now = options.dependencies?.now ?? (()=>new Date());
        this.#clock = options.dependencies?.clock ?? SYSTEM_CLOCK;
    }
    subscribe(options, signal) {
        if (this.#closed) {
            return Response.json({
                ok: false,
                code: "logcat-session-closed",
                error: "logcat session is closed"
            }, {
                status: 409
            });
        }
        if (signal?.aborted) {
            return Response.json({
                ok: false,
                code: "logcat-request-aborted",
                error: "request was aborted"
            }, {
                status: 499
            });
        }
        if (this.#subscribers.size >= this.#maxSubscribers) {
            return Response.json({
                ok: false,
                code: "logcat-subscriber-limit",
                error: `logcat subscriber limit is ${this.#maxSubscribers}`
            }, {
                status: 429
            });
        }
        try {
            this.#ensureChild();
        } catch (error) {
            return Response.json({
                ok: false,
                code: "logcat-start-failed",
                error: error instanceof Error ? error.message : String(error)
            }, {
                status: 502
            });
        }
        const packageName = (options.packageName ?? "").trim();
        const search = (options.search ?? "").trim().toLowerCase();
        let subscriber;
        const stream = new ReadableStream({
            start: (controller)=>{
                subscriber = {
                    id: this.#nextSubscriberId++,
                    active: true,
                    packageName,
                    search,
                    pids: new Set(),
                    controller,
                    queue: new BoundedLineQueue(this.#maxQueueLines, this.#maxQueueBytes),
                    totalDropped: 0,
                    sourceDroppedReported: this.#totals.sourceDroppedLines,
                    batchTimer: null,
                    waitingForPull: false,
                    pidTimer: null,
                    pidRefresh: null,
                    pidAbort: null,
                    signal,
                    abortListener: null
                };
                this.#subscribers.set(subscriber.id, subscriber);
                this.#sendControl(subscriber, "ready", {
                    serial: this.serial,
                    package: packageName || null,
                    search: search || null,
                    batchIntervalMs: this.#batchIntervalMs
                });
                if (packageName) {
                    this.#refreshPids(subscriber);
                    subscriber.pidTimer = this.#clock.setInterval(()=>this.#refreshPids(subscriber), this.#pidRefreshMs);
                }
                if (signal) {
                    const onAbort = ()=>this.#removeSubscriber(subscriber, true);
                    subscriber.abortListener = onAbort;
                    signal.addEventListener("abort", onAbort, {
                        once: true
                    });
                    if (signal.aborted) onAbort();
                }
            },
            pull: ()=>{
                if (!subscriber?.active) return;
                subscriber.waitingForPull = false;
                this.#flush(subscriber);
            },
            cancel: ()=>{
                if (subscriber) this.#removeSubscriber(subscriber);
            }
        });
        return new Response(stream, {
            headers: {
                "Content-Type": "text/event-stream; charset=utf-8",
                "Cache-Control": "no-cache",
                Connection: "keep-alive",
                "X-Accel-Buffering": "no"
            }
        });
    }
    close(reason = "device session closed") {
        if (this.#closed) return;
        this.#closed = true;
        this.#stopChild();
        for (const subscriber of [
            ...this.#subscribers.values()
        ]){
            this.#sendControl(subscriber, "close", {
                reason
            });
            this.#removeSubscriber(subscriber, true);
        }
    }
    snapshot() {
        let queuedLines = 0;
        let queuedBytes = 0;
        for (const subscriber of this.#subscribers.values()){
            queuedLines += subscriber.queue.lineCount;
            queuedBytes += subscriber.queue.byteCount;
        }
        return {
            serial: this.serial,
            closed: this.#closed,
            childActive: this.#child !== null,
            childTerminating: this.#terminatingChild !== null,
            childCount: Number(this.#child !== null) + Number(this.#terminatingChild !== null),
            subscribers: this.#subscribers.size,
            activePidLookups: this.#activePidLookups,
            queuedLines,
            queuedBytes,
            limits: {
                subscribers: this.#maxSubscribers,
                queueLinesPerSubscriber: this.#maxQueueLines,
                queueBytesPerSubscriber: this.#maxQueueBytes,
                sourceLineBytes: this.#maxSourceLineBytes,
                batchIntervalMs: this.#batchIntervalMs,
                terminationGraceMs: this.#terminationGraceMs
            },
            totals: {
                ...this.#totals
            },
            lastError: this.#lastError
        };
    }
    #ensureChild() {
        if (this.#child || this.#terminatingChild) return;
        const child = this.#spawn(this.serial);
        this.#child = child;
        this.#decoder = new StringDecoder("utf8");
        this.#lineBuffer = "";
        this.#discardingLongLine = false;
        this.#totals.childStarts++;
        child.stdout.on("data", (chunk)=>{
            if (this.#child !== child) return;
            this.#consumeSource(chunk);
        });
        child.stderr.on("data", (chunk)=>{
            if (this.#child !== child) return;
            const text = Buffer.isBuffer(chunk) ? chunk.toString("utf8") : chunk;
            const line = text.trim();
            if (!line) return;
            this.#lastError = line.slice(0, this.#maxSourceLineBytes);
            this.#dispatchLine(`[logcat stderr] ${this.#lastError}`);
        });
        child.once("error", (error)=>{
            if (this.#child !== child) return;
            this.#lastError = error.message;
            for (const subscriber of this.#subscribers.values()){
                this.#sendControl(subscriber, "error", {
                    error: error.message,
                    at: this.#now().toISOString()
                });
            }
        });
        child.once("close", (code, signal)=>{
            if (this.#terminatingChild === child) {
                this.#terminatingChild = null;
                if (this.#terminationTimer !== null) {
                    this.#clock.clearTimeout(this.#terminationTimer);
                    this.#terminationTimer = null;
                }
                if (!this.#closed && this.#subscribers.size > 0) {
                    this.#startReplacementChild();
                }
                return;
            }
            if (this.#child !== child) return;
            this.#child = null;
            this.#decoder.end();
            this.#decoder = new StringDecoder("utf8");
            this.#lineBuffer = "";
            this.#discardingLongLine = false;
            for (const subscriber of [
                ...this.#subscribers.values()
            ]){
                this.#sendControl(subscriber, "close", {
                    code,
                    signal
                });
                this.#removeSubscriber(subscriber, true);
            }
        });
    }
    #consumeSource(value) {
        let text = Buffer.isBuffer(value) ? this.#decoder.write(value) : value;
        if (this.#discardingLongLine) {
            const newline = text.indexOf("\n");
            if (newline === -1) return;
            text = text.slice(newline + 1);
            this.#discardingLongLine = false;
        }
        const lines = `${this.#lineBuffer}${text}`.split("\n");
        this.#lineBuffer = lines.pop() ?? "";
        for (const rawLine of lines){
            this.#acceptSourceLine(rawLine.replace(/\r$/, ""));
        }
        if (Buffer.byteLength(this.#lineBuffer, "utf8") > this.#maxSourceLineBytes) {
            this.#lineBuffer = "";
            this.#discardingLongLine = true;
            this.#recordSourceDrop();
        }
    }
    #acceptSourceLine(line) {
        if (!line) return;
        if (Buffer.byteLength(line, "utf8") > this.#maxSourceLineBytes) {
            this.#recordSourceDrop();
            return;
        }
        this.#dispatchLine(line);
    }
    #dispatchLine(line) {
        const value = {
            line,
            at: this.#now().toISOString()
        };
        for (const subscriber of this.#subscribers.values()){
            if (!this.#matches(subscriber, line)) continue;
            const dropped = subscriber.queue.push(value);
            if (dropped > 0) {
                subscriber.totalDropped += dropped;
                this.#totals.droppedLines += dropped;
            }
            this.#scheduleFlush(subscriber);
        }
    }
    #matches(subscriber, line) {
        if (subscriber.search && !line.toLowerCase().includes(subscriber.search)) {
            return false;
        }
        if (!subscriber.packageName) return true;
        const pid = line.trim().split(/\s+/, 4)[2];
        return Boolean(pid && subscriber.pids.has(pid) || line.includes(subscriber.packageName));
    }
    #scheduleFlush(subscriber) {
        if (!subscriber.active || subscriber.batchTimer !== null || subscriber.waitingForPull) {
            return;
        }
        subscriber.batchTimer = this.#clock.setTimeout(()=>{
            subscriber.batchTimer = null;
            this.#flush(subscriber);
        }, this.#batchIntervalMs);
    }
    #flush(subscriber) {
        if (!subscriber.active) return;
        if (subscriber.controller.desiredSize !== null && subscriber.controller.desiredSize <= 0) {
            subscriber.waitingForPull = true;
            return;
        }
        const batch = subscriber.queue.drain();
        const sourceDropped = this.#totals.sourceDroppedLines;
        if (batch.lines.length === 0 && batch.dropped === 0 && sourceDropped === subscriber.sourceDroppedReported) {
            return;
        }
        try {
            subscriber.controller.enqueue(encodeEvent("logs", {
                lines: batch.lines,
                dropped: batch.dropped,
                totalDropped: subscriber.totalDropped,
                sourceDropped
            }));
            subscriber.sourceDroppedReported = sourceDropped;
            this.#totals.batches++;
            this.#totals.deliveredLines += batch.lines.length;
        } catch  {
            this.#removeSubscriber(subscriber);
        }
    }
    #sendControl(subscriber, event, value) {
        if (!subscriber.active) return;
        try {
            subscriber.controller.enqueue(encodeEvent(event, value));
        } catch  {
            this.#removeSubscriber(subscriber);
        }
    }
    #refreshPids(subscriber) {
        if (!subscriber.active || !subscriber.packageName || subscriber.pidRefresh) {
            return;
        }
        const abort = new AbortController();
        subscriber.pidAbort = abort;
        this.#activePidLookups++;
        const refresh = Promise.resolve().then(()=>this.#resolvePackagePids(this.serial, subscriber.packageName, abort.signal)).then((pids)=>{
            if (subscriber.active) subscriber.pids = pids;
        }).catch((error)=>{
            if (subscriber.active) {
                this.#lastError = error instanceof Error ? error.message : String(error);
            }
        }).finally(()=>{
            this.#activePidLookups--;
            if (subscriber.pidRefresh === refresh) {
                subscriber.pidRefresh = null;
            }
            if (subscriber.pidAbort === abort) subscriber.pidAbort = null;
        });
        subscriber.pidRefresh = refresh;
    }
    #removeSubscriber(subscriber, closeStream = false) {
        if (!subscriber.active) return;
        subscriber.active = false;
        this.#subscribers.delete(subscriber.id);
        if (subscriber.batchTimer !== null) {
            this.#clock.clearTimeout(subscriber.batchTimer);
            subscriber.batchTimer = null;
        }
        if (subscriber.pidTimer !== null) {
            this.#clock.clearInterval(subscriber.pidTimer);
            subscriber.pidTimer = null;
        }
        if (subscriber.pidAbort) {
            const abort = subscriber.pidAbort;
            subscriber.pidAbort = null;
            abort.abort("logcat subscriber closed");
        }
        if (subscriber.abortListener && subscriber.signal) {
            subscriber.signal.removeEventListener("abort", subscriber.abortListener);
            subscriber.abortListener = null;
        }
        if (closeStream) {
            try {
                subscriber.controller.close();
            } catch  {}
        }
        if (this.#subscribers.size === 0) this.#stopChild();
    }
    #recordSourceDrop() {
        this.#totals.sourceDroppedLines++;
        for (const subscriber of this.#subscribers.values()){
            this.#scheduleFlush(subscriber);
        }
    }
    #startReplacementChild() {
        try {
            this.#ensureChild();
        } catch (error) {
            const message = error instanceof Error ? error.message : String(error);
            this.#lastError = message;
            for (const subscriber of [
                ...this.#subscribers.values()
            ]){
                this.#sendControl(subscriber, "error", {
                    error: message,
                    at: this.#now().toISOString()
                });
                this.#sendControl(subscriber, "close", {
                    reason: "logcat restart failed"
                });
                this.#removeSubscriber(subscriber, true);
            }
        }
    }
    #stopChild() {
        const child = this.#child;
        if (!child) return;
        this.#child = null;
        this.#terminatingChild = child;
        this.#lineBuffer = "";
        this.#discardingLongLine = false;
        this.#decoder.end();
        this.#decoder = new StringDecoder("utf8");
        this.#terminationTimer = this.#clock.setTimeout(()=>{
            this.#terminationTimer = null;
            if (this.#terminatingChild !== child) return;
            this.#totals.forcedKills++;
            try {
                child.kill("SIGKILL");
            } catch (error) {
                this.#lastError = error instanceof Error ? error.message : String(error);
            }
        }, this.#terminationGraceMs);
        try {
            child.kill("SIGTERM");
        } catch (error) {
            this.#lastError = error instanceof Error ? error.message : String(error);
        }
    }
}
